cssCode:
.liquid-shape {
  width: 150px; 
  height: 150px;
  background: linear-gradient(45deg, #ff007f, #00d2ff);
  box-shadow: 0 0 40px rgba(0, 210, 255, 0.6);
  animation: morphShape 4s ease-in-out infinite;
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), filter 0.3s ease;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

@keyframes morphShape {
  0% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
  50% { border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%; }
  100% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;overflow:hidden;';

const liquid = document.createElement('div');
liquid.className = 'liquid-shape';
c.appendChild(liquid);

let colorAngle = 0;

// દરેક ટચ પર અલગ કલર અને ઇફેક્ટ
liquid.addEventListener('pointerdown', () => {
  colorAngle += 85; 
  liquid.style.filter = `hue-rotate(${colorAngle}deg) brightness(1.3)`;
  liquid.style.transform = 'scale(1.4)';

  setTimeout(() => { 
    liquid.style.transform = 'scale(1)'; 
    liquid.style.filter = `hue-rotate(${colorAngle}deg) brightness(1)`;
  }, 400);
});
